import pg from './node_modules/pg/lib/index.js';
const startedAt=new Date().toISOString(),t=performance.now();
const value=process.env.FLOW_K01_QUERY_ADMIN_URL,url=new URL(value);
if(!['postgres:','postgresql:'].includes(url.protocol)||!['127.0.0.1','localhost','[::1]'].includes(url.hostname)||url.pathname!='/postgres'||url.search||value.includes('#'))throw new Error('LOCAL_ADMIN_REQUIRED');
const pool=new pg.Pool({connectionString:value,max:1,connectionTimeoutMillis:1000,statement_timeout:1500,lock_timeout:500,query_timeout:1800,application_name:'k01-integrated-headroom'});
let row=null,error=null,closed=false;pool.on('error',e=>{error={code:e.code??'POOL_ERROR'};});
try{row=(await pool.query('SELECT current_setting($1)::int AS maximum,(SELECT count(*)::int FROM pg_stat_activity) AS occupied',['max_connections'])).rows[0];}catch(e){error={code:e.code??'QUERY_ERROR'};}finally{await pool.end();closed=true;}
const available=row?row.maximum-row.occupied:null,passed=closed&&!error&&available>=35;
console.log(JSON.stringify({startedAt,endedAt:new Date().toISOString(),elapsedMs:performance.now()-t,...row,available,closed,error,passed}));if(!passed)process.exitCode=1;
